 #include <stdio.h>
 #include <stdlib.h>
 #include <time.h>

 #define MAX_NUM_PASSES 10

 struct player {
 int number;
 struct player *next;
 };
 typedef struct player player_t;

 player_t *Setup(int num_players);
 int PlayGame(player_t *players);
 void Display(player_t *players);

 int main() {
 int win, num_players;
 player_t *players;

 printf("How many players:= ");
 scanf("%d", &num_players);
 players = Setup(num_players);
 Display(players);
 win = PlayGame(players);
 printf("\nWinner = %d\n", ____A____ );
 return 0;
 }

player_t *Setup(int num_players) {
 player_t *temp, *prev, *players = NULL;
 int i;

 for (i = 1; i <= num_players; i++) {
 temp = (player_t *)malloc(sizeof(player_t));
 if (players == NULL) {
 players = temp;
 prev = temp;
 }
 temp->number = ____B____;
 temp->next = players;
 prev->next = temp;
 prev = temp;
 }
 return players;
}

int PlayGame(player_t *players) {
 player_t *p, *has_pillow;
 int rd, pass, i;

 srand(time(NULL));
 pass = 1;
 has_pillow = players;
 while (____C____ ) {
 rd = rand() % (MAX_NUM_PASSES - 1) + 1;

 for (i = 0; i < rd; i++) {
 p = has_pillow;
 has_pillow = has_pillow->next; /*** α ***/
 }
 ____D____;
 if (has_pillow == players) {
 players = has_pillow->next; /*** β ***/
 }
 free(has_pillow);
 has_pillow = p->next; /*** γ ***/
 printf("\nPass = %d", pass);
 printf("\nRandom Number:= %d", rd);
 printf("\n");
 Display(players);
 pass++;
 }
 return players->number;
}

void Display(player_t *players) {
 player_t *temp;

 printf("\nCurrent LinkedList:= ");
 temp = players;
 do {
 printf("%d ", temp->number);
 ____E____;
 } while (temp != players);
 }

